class vector3d {
public:
    float x, y, z;

    vector3d() {}
    vector3d(float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}
};

class vector4d {
public:
    float x, y, z, w;
};

class matrix4x4 {
public:
    vector4d x, y, z, w;
};

inline vector3d xform3d_1_homog(const matrix4x4& m44, const vector3d& sv)
{
    float w;
    w = m44.x.w * sv.x + m44.y.w * sv.y + m44.z.w * sv.z + m44.w.w;
    if (w)
        w = 1.0f / w;
    vector3d result;
    result.x = (m44.x.x * sv.x + m44.y.x * sv.y + m44.z.x * sv.z + m44.w.x) * w;
    result.y = (m44.x.y * sv.x + m44.y.y * sv.y + m44.z.y * sv.z + m44.w.y) * w;
    result.z = (m44.x.z * sv.x + m44.y.z * sv.y + m44.z.z * sv.z + m44.w.z) * w;
    return result;
}

struct nglQuad {
    char data[0x64];
};

extern void nglSetQuadRect(nglQuad *, float, float, float, float);

class PanelQuad {
    char before_quad[0x18];
    nglQuad quad;
    char before_coords[0x28];
    float x1, y1, x2, y2;
    char before_xform[0x78];

public:
    matrix4x4 Xform;
    char before_z[0x0c];
    float z;

    virtual ~PanelQuad() {}

private:
    void Animate();
};

void PanelQuad::Animate()
{
    vector3d wed[2];
    float diff_x = (x2-x1)/2.0f;
    float diff_y = (y2-y1)/2.0f;
    wed[0] = xform3d_1_homog(Xform, vector3d(-diff_x, -diff_y, z));
    wed[1] = xform3d_1_homog(Xform, vector3d(diff_x, diff_y, z));
    nglSetQuadRect(&quad, wed[0].x, wed[0].y, wed[1].x, wed[1].y);
}
